def regex_match(s: str, p: str) -> bool:
    if not p:  # if pattern is empty, it can only match an empty string
        return not s

    first_match = bool(s) and p[0] in {s[0], '.'}
    if len(p) >= 2 and p[1] == '*':
        # if pattern has at least two characters and the second character is '*', 
        # then we have two cases:
        # 1. ignore the '*' and move on to the next character in the pattern
        # 2. use the '*' to match the current character in the string
        return (regex_match(s, p[2:]) or
                first_match and regex_match(s[1:], p))
    else:
        # if pattern does not have '*' as the second character, 
        # then it must match the current character in the string
        return first_match and regex_match(s[1:], p[1:])

def regex_match(s: str, p: str) -> bool:
    """
    Return True if pattern p matches the whole of s.
    In p, '.' matches any single character and '*' matches zero or more of the preceding element.
    Every '*' is preceded by a valid character or '.'.

    :param s: The string to be matched
    :param p: The pattern to be matched
    :return: True if the pattern matches the string, False otherwise
    """

    # If the pattern is empty, it can only match an empty string
    if not p:
        return not s

    # If the string is empty but the pattern is not, there is no match
    if not s:
        return False

    # If the pattern's first character is '.', it matches any single character in the string
    if p[0] == '.':
        return regex_match(s[1:], p[1:])

    # If the pattern's first character is not '.' and it's not '*', we need to check if it matches the current character in the string
    if p[0] != '*':
        return p[0] == s[0] and regex_match(s[1:], p[1:])

    # If the pattern's first character is '*', it matches zero or more of the preceding element
    # We need to check two cases: the '*' matches zero elements, and the '*' matches one or more elements
    return regex_match(s, p[1:]) or (p[0] == s[0] or p[0] == '.') and regex_match(s[1:], p)

