    import re

    tokens = re.findall(r'\d+|\S', expr)
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    operators = []
    numbers = []

    def apply_operator():
        right = numbers.pop()
        left = numbers.pop()
        op = operators.pop()
        if op == '+':
            numbers.append(left + right)
        elif op == '-':
            numbers.append(left - right)
        elif op == '*':
            numbers.append(left * right)
        elif op == '/':
            numbers.append(int(left / right))

    for token in tokens:
        if token.isdigit():
            numbers.append(int(token))
        elif token in precedence:
            while (operators and operators[-1] in precedence and
                   precedence[operators[-1]] >= precedence[token]):
                apply_operator()
            operators.append(token)
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators[-1] != '(':
                apply_operator()
            operators.pop()

    while operators:
        apply_operator()

    return numbers[0]

