    def is_safe(board, row, col):
        for i in range(col):
            if board[row][i] == 1:
                return False
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False
        return True

    def solve_n_queens(board, col):
        if col >= n:
            return 1
        count = 0
        for i in range(n):
            if is_safe(board, i, col):
                board[i][col] = 1
                count += solve_n_queens(board, col + 1)
                board[i][col] = 0
        return count

    board = [[0 for _ in range(n)] for _ in range(n)]
    return solve_n_queens(board, 0)

import heapq

def dijkstra(n: int, edges: list[tuple[int, int, int]], src: int) -> list[int]:
    distances = [float('inf')] * n
    distances[src] = 0

    pq = [(0, src)]

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in [(v, w) for u, v, w in edges if u == current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return [d if d != float('inf') else -1 for d in distances]

def longest_palindrome(s: str) -> str:
    if not s:
        return ''

    start, end = 0, 0

    def expand_around_center(left: int, right: int) -> int:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return right - left - 1

    for i in range(len(s)):
        len1 = expand_around_center(i, i)  # Odd length palindrome
        len2 = expand_around_center(i, i + 1)  # Even length palindrome
        max_len = max(len1, len2)

        if max_len > end - start:
            start = i - (max_len - 1) // 2
            end = i + max_len // 2

    return s[start:end + 1]

