            i += 1
            j += 1

    while i < len(a):
        result.append(a[i])
        i += 1

    while j < len(b):
        result.append(b[j])
        j += 1

    return result

def paths_with_obstacles(grid: list[list[int]]) -> int:
    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]

    if grid[0][0] == 0:
        dp[0][0] = 1
    else:
        return 0

    for j in range(1, n):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1]

    for i in range(1, m):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]

    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[-1][-1]

def balanced_brackets(s: str) -> bool:
    stack = []
    matching_brackets = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in matching_brackets.values():
            stack.append(char)
        elif char in matching_brackets.keys():
            if not stack or stack.pop() != matching_brackets[char]:
                return False

    return not stack

def knapsack(weights: list[int], values: list[int], capacity: int) -> int:
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i - 1] <= w:
                dp[i][w] = max(dp[i - 1][w], values[i - 1] + dp[i - 1][w - weights[i - 1]])
            else:
                dp[i][w] = dp[i - 1][w]

    return dp[n][capacity]

def min_coins(coins: list[int], amount: int) -> int:
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0

    for coin in coins:
        for x in range(coin, amount + 1):
            dp[x] = min(dp[x], dp[x - coin] + 1)

    return dp[amount] if dp[amount] != float('inf') else -1

from collections import deque

def sliding_max(nums: list[int], k: int) -> list[int]:
    deq = deque()
    result = []

    for i in range(len(nums)):
        if deq and deq[0] == i - k:
            deq.popleft()

        while deq and nums[i] > nums[deq[-1]]:
            deq.pop()

        deq.append(i)

        if i >= k - 1:
            result.append(nums[deq[0]])

    return result

def caesar_shift(s: str, k: int) -> str:
    def shift_char(c: str, k: int) -> str:
        if c.islower():
            return chr((ord(c) - ord('a') + k) % 26 + ord('a'))
        elif c.isupper():
            return chr((ord(c) - ord('A') + k) % 26 + ord('A'))
        else:
            return c

    return ''.join(shift_char(c, k) for c in s)

def two_sum_indices(nums: list[int], target: int) -> tuple[int, int] | None:
    num_to_index = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return (num_to_index[complement], i)
        num_to_index[num] = i
    return None

def binary_search(nums: list[int], target: int) -> int:
    left, right = 0, len(nums) - 1
    result = -1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            result = mid
            right = mid - 1  # Continue searching in the left half
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    # Return the index of the first occurrence of the target
    return result if nums[result] == target else -1

def lis_length(nums: list[int]) -> int:
    tails = []
    for num in nums:
        i = bisect_left(tails, num)
        if i == len(tails):
            tails.append(num)
        else:
            tails[i] = num
    return len(tails)

def matmul(a: list[list[float]], b: list[list[float]]) -> list[list[float]]:
    if len(a[0]) != len(b):
        raise ValueError("Number of columns in a must be equal to number of rows in b")

    result = [[0] * len(b[0]) for _ in range(len(a))]

    for i in range(len(a)):
        for j in range(len(b[0])):
            for k in range(len(b)):
                result[i][j] += a[i][k] * b[k][j]

    return result

def flatten_once(nested: list[list]) -> list:
    flat_list = []
    for sublist in nested:
        flat_list.extend(sublist)
    return flat_list

def trapped_water(heights: list[int]) -> int:
    if not heights:
        return 0

    left, right = 0, len(heights) - 1
    left_max, right_max = heights[left], heights[right]
    water_trapped = 0

    while left < right:
        if heights[left] < heights[right]:
            if heights[left] >= left_max:
                left_max = heights[left]
            else:
                water_trapped += left_max - heights[left]
            left += 1
        else:
            if heights[right] >= right_max:
                right_max = heights[right]
            else:
                water_trapped += right_max - heights[right]
            right -= 1

    return water_trapped

def roman_to_int(s: str) -> int:
    roman_values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = prev_value = 0
    for char in s:
        current_value = roman_values[char]
        if current_value > prev_value:
            total += current_value - 2 * prev_value
        else:
            total += current_value
        prev_value = current_value
    return total

def factorial(n: int) -> int:
    if n < 0:
        raise ValueError("n must be a non-negative integer.")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def fizzbuzz_list(n: int) -> list[str]:
