def rle_encode(s: str) -> str:
    if not s:
        return ''

    result = ''
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result += current_char + str(count)
            current_char = char
            count = 1

    # Append the last run
    result += current_char + str(count)

    return result

