        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack:
                return False
            elif char == ")" and stack[-1] == "(" or \
                 char == "]" and stack[-1] == "[" or \
                 char == "}" and stack[-1] == "{":
                stack.pop()
            else:
                return False
    return not stack

def binary_search(nums: list[int], target: int) -> int:
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] < target:
            left = mid + 1
        elif nums[mid] > target:
            right = mid - 1
        else:
            if mid == 0 or nums[mid - 1] != target:
                return mid
            else:
                right = mid - 1

    return -1

