            op = expr[index]
            index += 1
            num2 = parse_term()
            if op == '*':
                num1 *= num2
            else:
                num1 = int(num1 / num2)
        return num1

    def parse_expr():
        num1 = parse_factor()
        while index < len(expr) and expr[index] in ('+', '-'):
            op = expr[index]
            index += 1
            num2 = parse_factor()
            if op == '+':
                num1 += num2
            else:
