import heapq

def dijkstra(n: int, edges: list[tuple[int, int, int]], src: int) -> list[int]:
    distances = {i: float('inf') for i in range(n)}
    distances[src] = 0

    queue = [(0, src)]

    while queue:
        current_distance, node = heapq.heappop(queue)

        if current_distance > distances[node]:
            continue

        for neighbor, weight in [(v, w) for u, v, w in edges if u == node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(queue, (distance, neighbor))

    return [distances[i] if distances[i] != float('inf') else -1 for i in range(n)]

def regex_match(s: str, p: str) -> bool:
    def helper(s: str, p: str) -> bool:
        if not p:
            return not s

        first_match = bool(s) and p[0] in {s[0], '.'}

        if len(p) >= 2 and p[1] == '*':
            return helper(s, p[2:]) or (first_match and helper(s[1:], p))
        else:
            return first_match and helper(s[1:], p)

    return helper(s, p)

def next_permutation(nums: list[int]) -> list[int]:
    k, l = -1, 0
    for i in range(len(nums) - 1):
        if nums[i] < nums[i + 1]:
            k = i
    if k == -1:
        return sorted(nums)
    for i in range(len(nums)):
        if nums[i] > nums[k]:
            l = i
    nums[k], nums[l] = nums[l], nums[k]
    nums[k + 1:] = reversed(nums[k + 1:])
    return nums.copy()

