                return False
    return not stack

def binary_search(nums: list[int], target: int) -> int:
    left, right = 0, len(nums) - 1
    result = -1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        elif nums[mid] > target:
            right = mid - 1
        else:
            result = mid
            right = mid - 1

    if result != -1 and nums[result] != target:
        return -1

    while result > 0 and nums[result - 1] == target:
        result -= 1

    return result

