def two_sum_indices(nums, target):
    nums.sort()
    i, j = 0, len(nums) - 1
    while i < j:
        if nums[i] + nums[j] == target:
            break
        elif nums[i] + nums[j] > target:
            j -= 1
        else:
            i += 1
    else:
        return None

    while i < len(nums) - 1 and nums[i] == nums[i + 1]:
        i += 1

    while j > 0 and nums[j - 1] == nums[j]:
        j -= 1

    return (i, j)

