def lis_length(nums: list[int]) -> int:
    if not nums:
        return 0

    dp = [1] * len(nums)
    max_len = 1

    for i in range(len(nums)):
        for j in range(i):
            if nums[i] > nums[j] and dp[i] < dp[j] + 1:
                dp[i] = dp[j] + 1
                max_len = max(max_len, dp[i])

    return max_len

def regex_match(s, p):
    if not p:
        return not s

    i, j = 0, 0
    while i < len(s) and j < len(p):
        if p[j] == s[i] or p[j] == '.':
            i += 1
            j += 1
        elif p[j] == '*':
            if p[j - 1] == s[i] or p[j - 1] == '.':
                i += 1
                j += 1
            else:
                j -= 1
    return j == len(p)

