def sliding_max(nums: list[int], k: int) -> list[int]:
    n = len(nums)
    if k > n:
        return []
    result = []
    queue = []
    for i in range(k):
        while queue and nums[i] >= nums[queue[-1]]:
            queue.pop()
        queue.append(i)
    result.append(nums[queue[0]])
    for i in range(k, n):
        while queue and queue[0] <= i - k:
            queue.pop(0)
        while queue and nums[i] >= nums[queue[-1]]:
            queue.pop()
        queue.append(i)
        result.append(nums[queue[0]])
    return result

def evaluate(expr: str) -> int:
    expr = expr.replace(' ', '')
    if not expr:
        return 0
    if expr.isdigit():
        return int(expr)
    i = 0
    while i < len(expr):
        if expr[i].isdigit():
            num = 0
            while i < len(expr) and expr[i].isdigit():
                num = num * 10 + int(expr[i])
                i += 1
            if i < len(expr) and expr[i] in "+-* /":
                op = expr[i]
                i += 1
                right = evaluate(expr[i:])
                if op == "+":
                    return num + right
                elif op == "-":
                    return num - right
                elif op == "*":
                    return num * right
                else:
                    return num // right
            else:
                return num
        else:
            i += 1

def min_window(s: str, t: str) -> str:
    if not t:
        return ''

    dict_t = {}
    for c in t:
        dict_t[c] = dict_t.get(c, 0) + 1

    required = len(dict_t)
    formed = 0
    window_counts = {}

    l, r = 0, 0
    ans = float('inf'), None, None 

    while r < len(s):
        character = s[r]
        window_counts[character] = window_counts.get(character, 0) + 1
        if character in dict_t and window_counts[character] == dict_t[character]:
            formed += 1

        while l <= r and formed == required:
            character = s[l]

            if r - l + 1 < ans[0]:
                ans = (r - l + 1, l, r)

            window_counts[character] -= 1
            if character in dict_t and window_counts[character] < dict_t[character]:
                formed -= 1
            l += 1
        r += 1
    return '' if ans[0] == float('inf') else s[ans[1] : ans[2] + 1]

